package com.nthexperience.desktop;

import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.function.Consumer;

/** Saved links and read state are local. Opening an article uses the existing browser. */
final class EightReadingList extends LinearLayout {
    static final String KEY="eight_reading_items";static final int MAX=200;
    final DesktopStore store;final Consumer<String> open;final LinearLayout rows;boolean unread;
    EightReadingList(Context c,DesktopStore store,Consumer<String> open){super(c);this.store=store;this.open=open;setOrientation(VERTICAL);setBackgroundColor(0xfffaf7f2);TenAppearance.preserve(this);setContentDescription("Eight Reading List");
        TextView title=Aero.text(c,"Reading List",34,0xff222222);title.setPadding(dp(24),dp(18),dp(16),dp(18));addView(title);
        LinearLayout commands=new LinearLayout(c);for(String label:new String[]{"Add a link","All / Unread"}){TextView b=button(label,()->{if(label.equals("Add a link"))addDialog();else{unread=!unread;render();}});commands.addView(b,new LayoutParams(0,dp(48),1));}addView(commands);ScrollView scroll=new ScrollView(c);rows=Aero.column(c);rows.setPadding(dp(20),dp(12),dp(20),dp(20));scroll.addView(rows);addView(scroll,new LayoutParams(-1,0,1));render();}
    int dp(int n){return Aero.dp(getContext(),n);}
    static JSONArray items(DesktopStore store){try{return new JSONArray(store.prefs.getString(KEY,"[]"));}catch(Exception e){return new JSONArray();}}
    static boolean add(DesktopStore store,String url,String title){if(!BrowserUrls.web(url)||url.length()>4096)return false;JSONArray old=items(store),out=new JSONArray();JSONObject item=new JSONObject();GadgetLayout.put(item,"url",url);GadgetLayout.put(item,"title",title==null||title.trim().isEmpty()?url:title.substring(0,Math.min(300,title.length())));GadgetLayout.put(item,"read",false);GadgetLayout.put(item,"saved",System.currentTimeMillis());out.put(item);for(int i=0;i<old.length()&&out.length()<MAX;i++){JSONObject row=old.optJSONObject(i);if(row!=null&&!row.optString("url").equals(url))out.put(row);}store.prefs.edit().putString(KEY,out.toString()).apply();return true;}
    static void validate(String value)throws JSONException{JSONArray rows=new JSONArray(value);if(rows.length()>MAX)throw new JSONException("Too many Reading List items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!BrowserUrls.web(row.getString("url"))||row.getString("url").length()>4096||row.getString("title").length()>300||!(row.get("read") instanceof Boolean))throw new JSONException("Invalid saved reading item");}}
    TextView button(String title,Runnable action){TextView b=Aero.text(getContext(),title,15,0xff9a352b);b.setGravity(Gravity.CENTER_VERTICAL);b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setMinHeight(dp(48));b.setContentDescription(title);b.setFocusable(true);b.setBackground(Aero.selection(getContext()));b.setOnClickListener(v->action.run());return b;}
    void render(){rows.removeAllViews();JSONArray list=items(store);int shown=0;for(int i=0;i<list.length();i++){JSONObject row=list.optJSONObject(i);if(row==null||unread&&row.optBoolean("read"))continue;shown++;LinearLayout item=Aero.column(getContext());TextView title=button(row.optString("title"),()->{mark(row.optString("url"),true,false);open.accept("favorite-web:"+row.optString("url"));});title.setTextSize(21);title.setContentDescription("Read saved article: "+row.optString("title"));item.addView(title);TextView url=Aero.text(getContext(),(row.optBoolean("read")?"Read":"Unread")+" · "+row.optString("url"),12,0xff555555);url.setMaxLines(2);url.setPadding(dp(12),0,dp(12),dp(14));item.addView(url);TextView more=button("Mark / Share / Remove",()->Aero.dialog(getContext()).setTitle(row.optString("title")).setItems(new String[]{row.optBoolean("read")?"Mark unread":"Mark read","Share","Remove"},(d,n)->{if(n==1)getContext().startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,row.optString("url")),"Share saved article"));else mark(row.optString("url"),!row.optBoolean("read"),n==2);}).show());more.setContentDescription("Saved article commands: "+row.optString("title"));item.addView(more);rows.addView(item);}
        if(shown==0){TextView empty=Aero.text(getContext(),unread?"No unread articles.":"Save a web page from Browser or News, or add a link here. Saved links need a connection to load; PDFs open locally in Reader.",18,0xff555555);rows.addView(empty);}}
    void mark(String url,boolean read,boolean remove){JSONArray old=items(store),out=new JSONArray();for(int i=0;i<old.length();i++){JSONObject row=old.optJSONObject(i);if(row==null)continue;if(row.optString("url").equals(url)){if(remove)continue;GadgetLayout.put(row,"read",read);}out.put(row);}store.prefs.edit().putString(KEY,out.toString()).apply();render();}
    void addDialog(){LinearLayout fields=Aero.column(getContext());EditText url=new EditText(getContext()),title=new EditText(getContext());url.setSingleLine();url.setHint("https://…");url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);url.setContentDescription("Saved article address");title.setSingleLine();title.setHint("Title (optional)");fields.addView(url);fields.addView(title);android.app.AlertDialog d=Aero.dialog(getContext()).setTitle("Add to Reading List").setView(fields).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{if(!add(store,url.getText().toString().trim(),title.getText().toString())){url.setError("Enter a complete http or https address");return;}d.dismiss();render();}));d.show();}
    @Override public void onVisibilityAggregated(boolean visible){super.onVisibilityAggregated(visible);if(visible&&rows!=null)render();}
}
